begin;
create temporary table date_ctx as select s.id sid,a.user_id a,b.user_id b,gen_random_uuid() outsider from public.partner_spaces s join public.space_members a on a.space_id=s.id join public.space_members b on b.space_id=s.id and b.user_id<>a.user_id where s.closed_at is null and not exists(select 1 from public.couple_dates d where d.space_id=s.id) limit 1;
grant select on date_ctx to authenticated,anon;
create function pg_temp.date_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAILED: %',label;end if;end$$;
create function pg_temp.date_denied(q text) returns void language plpgsql security invoker as $$begin begin execute q;raise exception 'FAILED: unauthorized operation';exception when insufficient_privilege then null;end;end$$;
do $$begin if not exists(select 1 from date_ctx) then raise exception 'Need an active test couple without an existing date';end if;end$$;
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true) from date_ctx;
select pg_temp.date_assert((public.save_couple_date(sid,10000,0)->>'version')::bigint=1,'first partner creates') from date_ctx;
select pg_temp.date_assert((public.save_couple_date(sid,10000,0)->>'version')::bigint=1,'same desired date retries safely') from date_ctx;
select set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true) from date_ctx;
select pg_temp.date_assert((select since_day from public.couple_dates where space_id=(select sid from date_ctx))=10000,'second partner reads same date');
select pg_temp.date_assert((public.save_couple_date(sid,11000,1)->>'version')::bigint=2,'second partner edits') from date_ctx;
select set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true) from date_ctx;
select pg_temp.date_assert((select since_day from public.couple_dates where space_id=(select sid from date_ctx))=11000,'first partner sees edited date');
do $$declare t date_ctx%rowtype;begin select * into t from date_ctx;
 begin perform public.save_couple_date(t.sid,12000,1);raise exception 'FAILED: stale date overwrite';exception when serialization_failure then null;end;
 begin perform public.save_couple_date(t.sid,999999,2);raise exception 'FAILED: future date';exception when check_violation then null;end;
 begin perform public.save_couple_date(t.sid,-30000,2);raise exception 'FAILED: too old date';exception when check_violation then null;end;
end$$;
select pg_temp.date_denied('update public.couple_dates set version=500');
select pg_temp.date_denied('delete from public.couple_dates');
select pg_temp.date_denied(format('insert into public.couple_dates(space_id,since_day) values(%L,10000)',gen_random_uuid()));
select set_config('request.jwt.claims',jsonb_build_object('sub',outsider,'role','authenticated')::text,true) from date_ctx;
select pg_temp.date_assert((select count(*) from public.couple_dates)=0,'outsider reads none');
select pg_temp.date_denied(format('select public.save_couple_date(%L,10000,2)',sid)) from date_ctx;
set local role anon;
select pg_temp.date_denied('select * from public.couple_dates');
select pg_temp.date_denied(format('select public.save_couple_date(%L,10000,2)',sid)) from date_ctx;
reset role;
select 'Both partner writes/reads, version conflicts, safe retry, date validation, immutable metadata, outsider and anonymous denials passed. All fixtures rolled back.' as result;
rollback;
